package it.appnote;
import android.app.*;import android.os.*;import android.graphics.Color;import android.widget.*;import android.view.*;import java.time.*;import java.util.*;import org.json.*;
public class Editor extends Activity {
 LinearLayout panel; EditText text; String date="",id=""; int bg=0xff292929,fg=Color.WHITE; Button day;
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());panel.addView(b);return b;}
 public void onCreate(Bundle b){super.onCreate(b);String key=getIntent().getStringExtra("id");if(key!=null){for(JSONObject x:Store.all(this))if(x.optString("id").equals(key)){new AlertDialog.Builder(this).setItems(new String[]{"Modifica","Elimina"},(d,n)->{if(n==0)show(x);else new AlertDialog.Builder(this).setMessage("Eliminare?").setPositiveButton("Elimina",(a,z)->{Store.save(this,null,key);finish();}).setNegativeButton("Annulla",(a,z)->finish()).show();}).setOnCancelListener(d->finish()).show();return;}}show(null);}
 void show(JSONObject x){if(x!=null){id=x.optString("id");date=x.optString("date");bg=x.optInt("bg",bg);fg=x.optInt("fg",fg);}else id=UUID.randomUUID().toString();ScrollView scroll=new ScrollView(this);panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(16),dp(32),dp(16),dp(32));scroll.addView(panel);setContentView(scroll);day=button(date.isEmpty()?"Data":date,()->{LocalDate d=date.isEmpty()?LocalDate.now():LocalDate.parse(date);new DatePickerDialog(this,(v,y,m,k)->{date=LocalDate.of(y,m+1,k).toString();day.setText(date);},d.getYear(),d.getMonthValue()-1,d.getDayOfMonth()).show();});button("Senza data",()->{date="";day.setText("Data");});text=new EditText(this);text.setHint("Nota o appuntamento");text.setMinLines(3);if(x!=null)text.setText(x.optString("text"));panel.addView(text);button("Colore sfondo",()->pick(bg,c->{bg=c;preview();}));button("Colore carattere",()->pick(fg,c->{fg=c;preview();}));preview();button("Salva",()->{if(text.getText().toString().trim().isEmpty()){text.setError("Inserisci testo");return;}try{JSONObject j=new JSONObject();j.put("id",id);j.put("date",date);j.put("text",text.getText().toString());j.put("bg",bg);j.put("fg",fg);Store.save(this,j,id);finish();}catch(Exception e){}});button("Sfondo appuntamenti di oggi",()->pick(Store.p(this).getInt("todayBg",Color.WHITE),c->{Store.p(this).edit().putInt("todayBg",c).apply();Widget.refresh(this);}));button("Carattere appuntamenti di oggi",()->pick(Store.p(this).getInt("todayFg",0xffcc0000),c->{Store.p(this).edit().putInt("todayFg",c).apply();Widget.refresh(this);}));if(x==null)for(JSONObject j:Store.all(this))button(j.optString("text"),()->show(j));}
 void preview(){text.setBackgroundColor(bg);text.setTextColor(fg);text.setHintTextColor(fg);}
 interface Pick{void apply(int c);} void pick(int initial,Pick p){LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText hex=new EditText(this);hex.setSingleLine();hex.setText(String.format("#%06X",initial&0xffffff));l.addView(hex);int[] colors={Color.WHITE,Color.BLACK,0xff292929,0xffcc0000,0xff198c45,0xff2866bb,0xffe9c84c,0xffe9b7d0,0xffff9138,0xff8357ab};for(int i=0;i<2;i++){LinearLayout row=new LinearLayout(this);l.addView(row);for(int k=0;k<5;k++){int c=colors[i*5+k];Button b=new Button(this);b.setBackgroundColor(c);row.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));b.setOnClickListener(v->hex.setText(String.format("#%06X",c&0xffffff)));}}AlertDialog a=new AlertDialog.Builder(this).setView(l).setNegativeButton("Annulla",null).setPositiveButton("OK",null).create();a.setOnShowListener(v->a.getButton(-1).setOnClickListener(w->{try{p.apply(Color.parseColor(hex.getText().toString()));a.dismiss();}catch(Exception e){hex.setError("#RRGGBB");}}));a.show();}
}
